#include "Monstey_NavCompactCooker.hpp"
#include "Monstey_NavigationBoundaryQuery.hpp"
#include "Monstey_StaticNavFaceBounds.hpp"
#include "Monstey_Havok.hpp"
#include "Monstey_Core.hpp"
#include <algorithm>
#include <array>
#include <bit>
#include <iostream>
using namespace Monstey;
namespace {
Monstey_Bytes Records(Monstey_Havok&g,std::size_t mesh,std::string_view field,std::size_t stride){Monstey_Bytes out;for(const auto id:g.Node(g.Field(mesh,field)).elements){const auto&raw=g.Node(id).original_storage;Monstey_Require(raw.size()==stride,"Actual record stride differs");out.insert(out.end(),raw.begin(),raw.end());}return out;}
bool Intersects(const Monstey_NavigationAabb&a,const Monstey_NavigationAabb&b){for(unsigned axis=0;axis<3;++axis)if(a.minimum[axis]>b.maximum[axis]||b.minimum[axis]>a.maximum[axis])return false;return true;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==3,"SOURCE_HKAI NEW_REPORT");const std::filesystem::path source=argv[1],output=argv[2];Monstey_RequireOfflineOutput(output,std::array{source});const auto bytes=Monstey_ReadFile(source);const auto hash=Monstey_HashSha256(bytes);Monstey_Require(hash=="b9fb6380798b09110a8db133ea6139e17db88ec5cad123fc6aa1fe1b038008ee","Actual source pin differs");Monstey_Require(bytes.size()>=28&&Monstey_U32(bytes,0)==0x49414b48&&Monstey_U32(bytes,4)==3&&Monstey_U32(bytes,12)==bytes.size()-20,"Actual HKAI3 envelope differs");Monstey_Havok graph(std::span(bytes).subspan(16,bytes.size()-20));const auto meshes=graph.Objects("hkaiNavMesh");Monstey_Require(meshes.size()==1,"One actual principal mesh required");const auto faces=Records(graph,meshes[0],"faces",16),edges=Records(graph,meshes[0],"edges",20),vertices=Records(graph,meshes[0],"vertices",16);const auto cooked=Monstey_NavCookCompactMesh(faces,edges,vertices);const auto count=faces.size()/16;Monstey_Require(count==152&&edges.size()/20==456&&vertices.size()/16==142&&cooked.nodes.size()/6==303,"Actual native array counts differ");std::vector<Monstey_NavigationAabb>bounds;for(unsigned i=0;i<count;++i){const auto b=Monstey_StaticNavFaceBounds(faces,edges,vertices,i);bounds.push_back({b.minimum,b.maximum});}std::size_t queries=0,trueHits=0,returned=0,minimumHits=count;
const auto CheckQuery=[&](const Monstey_NavigationAabb&q){const auto hits=Monstey_NavigationCompactTreeQuery({cooked.nodes,cooked.bounds},q);std::vector<bool>seen(count);for(const auto hit:hits){Monstey_Require(hit<count&&!seen[hit],"Actual compact payload repeated or outside source");seen[hit]=true;}for(std::size_t i=0;i<count;++i)if(Intersects(q,bounds[i])){Monstey_Require(seen[i],"Actual full cooker omitted true native face bound");++trueHits;}minimumHits=std::min(minimumHits,hits.size());returned+=hits.size();++queries;};
for(const auto&b:bounds)CheckQuery(b);for(std::size_t i=0;i<vertices.size()/16;++i){Monstey_NavigationVector4 point{};for(unsigned axis=0;axis<4;++axis)point[axis]=std::bit_cast<float>(Monstey_U32(vertices,i*16+axis*4));CheckQuery({point,point});}Monstey_Require(minimumHits<count,"Actual cooker queries failed to cull any faces");Monstey_Require(Monstey_HashSha256(source)==hash,"Actual source changed");Monstey_WriteNewText(output,Monstey_Json::object({{"status","PASS"},{"source_sha256",hash},{"faces",count},{"edges",edges.size()/20},{"vertices",vertices.size()/16},{"compact_nodes",cooked.nodes.size()/6},{"compact_bytes",cooked.nodes.size()},{"compact_sha256",Monstey_HashSha256(cooked.nodes)},{"queries",queries},{"true_intersections_retained",trueHits},{"returned_face_hits",returned},{"minimum_hits_per_query",minimumHits},{"native_optimizer_finalization",true},{"supplied_tree_required",false},{"runtime_verified",false},{"original_program_executed",false}}).dump(2)+"\n");std::cout<<"PASS actual full cooker "<<queries<<" conservative queries / "<<trueHits<<" true intersections\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
